const Fastify = require('./fastify')
process.on('unhandledRejection', (e) => { console.log('UNHANDLED REJECTION:', e && e.code, e && e.message) })
process.on('uncaughtException', (e) => { console.log('UNCAUGHT:', e && e.code, e && e.message) })

const mode = process.argv[2]

const app = Fastify({ logger: false })
if (mode === 'sync') {
  app.addHook('onSend', (req, reply, payload, done) => {
    reply.raw.writeHead(200)
    reply.raw.end()
    done(null, payload)
  })
} else if (mode === 'async') {
  app.addHook('onSend', async (req, reply, payload) => {
    reply.raw.writeHead(200)
    reply.raw.end()
    return payload
  })
} else if (mode === 'preser') {
  app.addHook('preSerialization', async (req, reply, payload) => {
    reply.raw.writeHead(200)
    reply.raw.end()
    return payload
  })
} else if (mode === 'none') {
  app.addHook('onRequest', async (req, reply) => {
    reply.raw.writeHead(200)
    reply.raw.end()
  })
}
app.get('/', async () => ({ hello: 'world' }))
app.inject({ method: 'GET', url: '/' }, (err, res) => {
  console.log('inject cb:', err && err.message, res && res.statusCode)
})
setTimeout(() => process.exit(0), 300)

